SELECT cmsprovider_1.hcpcs_description AS hcpcs_description,   CAST(cmsprovider_1.nppes_provider_zip AS BIGINT) AS nppes_provider_zip,   AVG(CAST(cmsprovider_1.average_submitted_chrg_amt AS double precision)) AS avg_average_submitted_chrg_amt_ok FROM cmsprovider_1 WHERE ((cmsprovider_1.hcpcs_description IN ('Removal of joint lining from two or more knee joint compartments using an endoscope', 'Removal of knee cap', 'Removal of knee joint covering')) AND (cmsprovider_1.nppes_provider_state = 'CA')) GROUP BY cmsprovider_1.hcpcs_description,   cmsprovider_1.nppes_provider_zip,   cmsprovider_1.nppes_provider_zip;
